package org.keycloak.protocol.oid4vc.utils;

import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.List;

/**
 * Standalone test to demonstrate the hasArrayObjectConflict bug.
 * Uses reflection to call the private static method, and a simple main method
 * to demonstrate the bug without JUnit.
 */
public class ClaimsPathPointerBugTest {

    public static void main(String[] args) {
        boolean allPassed = true;

        // Test 1: Two paths with common prefix should NOT conflict
        // ["vc", "credentialSubject", "name"] vs ["vc", "credentialSubject", "email"]
        List<Object> path1 = Arrays.asList("vc", "credentialSubject", "name");
        List<Object> path2 = Arrays.asList("vc", "credentialSubject", "email");

        boolean conflict = hasArrayObjectConflict(path1, path2);
        System.out.println("Test 1: Paths with common prefix should NOT conflict");
        System.out.println("  Path1: " + path1);
        System.out.println("  Path2: " + path2);
        System.out.println("  Expected conflict: false");
        System.out.println("  Actual conflict: " + conflict);
        if (conflict) {
            System.out.println("  RESULT: FAIL (BUG - false positive conflict detected)");
            allPassed = false;
        } else {
            System.out.println("  RESULT: PASS");
        }
        System.out.println();

        // Test 2: Two identical paths should NOT trigger hasArrayObjectConflict (they're handled by equals check)
        List<Object> path3 = Arrays.asList("a", "b");
        List<Object> path4 = Arrays.asList("a", "b");
        boolean conflict2 = hasArrayObjectConflict(path3, path4);
        System.out.println("Test 2: Identical paths should NOT be reported by hasArrayObjectConflict");
        System.out.println("  Path1: " + path3);
        System.out.println("  Path2: " + path4);
        System.out.println("  Expected conflict: false");
        System.out.println("  Actual conflict: " + conflict2);
        if (conflict2) {
            System.out.println("  RESULT: FAIL (BUG - duplicate check should be in isConflicting)");
            allPassed = false;
        } else {
            System.out.println("  RESULT: PASS");
        }
        System.out.println();

        // Test 3: Array vs object conflict should still be detected
        // null (array selection) vs String (object selection)
        List<Object> path5 = Arrays.asList("items", null);
        List<Object> path6 = Arrays.asList("items", "name");
        boolean conflict3 = hasArrayObjectConflict(path5, path6);
        System.out.println("Test 3: Array vs object conflict should be detected");
        System.out.println("  Path1: " + path5);
        System.out.println("  Path2: " + path6);
        System.out.println("  Expected conflict: true");
        System.out.println("  Actual conflict: " + conflict3);
        if (!conflict3) {
            System.out.println("  RESULT: FAIL (should detect array/object conflict)");
            allPassed = false;
        } else {
            System.out.println("  RESULT: PASS");
        }
        System.out.println();

        // Test 4: Specific array index vs null (all elements) should still be detected
        List<Object> path7 = Arrays.asList("items", 0);
        List<Object> path8 = Arrays.asList("items", null);
        boolean conflict4 = hasArrayObjectConflict(path7, path8);
        System.out.println("Test 4: Specific array index vs all elements conflict should be detected");
        System.out.println("  Path1: " + path7);
        System.out.println("  Path2: " + path8);
        System.out.println("  Expected conflict: true");
        System.out.println("  Actual conflict: " + conflict4);
        if (!conflict4) {
            System.out.println("  RESULT: FAIL (should detect array index conflict)");
            allPassed = false;
        } else {
            System.out.println("  RESULT: PASS");
        }
        System.out.println();

        System.out.println("========================================");
        if (allPassed) {
            System.out.println("ALL TESTS PASSED");
            System.exit(0);
        } else {
            System.out.println("SOME TESTS FAILED - BUG CONFIRMED");
            System.exit(1);
        }
    }

    /**
     * Copy of the buggy hasArrayObjectConflict method from ClaimsPathPointer.java
     * to demonstrate the issue.
     */
    private static boolean hasArrayObjectConflict(List<Object> path1, List<Object> path2) {
        int minLength = Math.min(path1.size(), path2.size());

        for (int i = 0; i < minLength; i++) {
            Object comp1 = path1.get(i);
            Object comp2 = path2.get(i);

            // If components are different types and one is null (array selection) and the other is string (object selection)
            if (comp1 == null && comp2 instanceof String) {
                return true;
            }
            if (comp2 == null && comp1 instanceof String) {
                return true;
            }

            // If components are different types and one is integer (specific array index) and the other is null (all array elements)
            if (comp1 == null && comp2 instanceof Integer) {
                return true;
            }
            if (comp2 == null && comp1 instanceof Integer) {
                return true;
            }

            // BUG: If components are equal, return true (as suggested by reviewer)
            // This is wrong - equal components in a common prefix are NORMAL and should not trigger a conflict
            if (java.util.Objects.equals(comp1, comp2)) {
                return true;  // BUG: returns true for shared prefix components
            }
        }

        return false;
    }
}

