    @Test
    public void testValidateClaimsDescriptionsWithSharedPrefixShouldNotConflict() {
        // Two paths with common prefix should NOT be considered conflicting
        // This is the correct behavior - paths like ["vc","credentialSubject","name"]
        // and ["vc","credentialSubject","email"] are different claims, not conflicting ones
        ClaimsDescription claim1 = new ClaimsDescription();
        claim1.setPath(Arrays.asList("vc", "credentialSubject", "name"));
        claim1.setMandatory(false);

        ClaimsDescription claim2 = new ClaimsDescription();
        claim2.setPath(Arrays.asList("vc", "credentialSubject", "email"));
        claim2.setMandatory(false);

        List<ClaimsDescription> claims = Arrays.asList(claim1, claim2);

        // Should return true (valid, no conflict) because these are different paths
        assertTrue("Claims with shared prefix but different final components should NOT conflict",
                ClaimsPathPointer.validateClaimsDescriptions(claims));
    }

    @Test
    public void testValidateClaimsDescriptionsWithIdenticalPathsShouldConflict() {
        // Two paths that are identical SHOULD be considered conflicting
        ClaimsDescription claim1 = new ClaimsDescription();
        claim1.setPath(Arrays.asList("vc", "credentialSubject", "name"));
        claim1.setMandatory(false);

        ClaimsDescription claim2 = new ClaimsDescription();
        claim2.setPath(Arrays.asList("vc", "credentialSubject", "name"));
        claim2.setMandatory(false);

        List<ClaimsDescription> claims = Arrays.asList(claim1, claim2);

        // Should return false (conflict) because these are the same path
        assertFalse("Claims with identical paths SHOULD conflict",
                ClaimsPathPointer.validateClaimsDescriptions(claims));
    }

