import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.lang.reflect.Method;
import java.security.cert.CertificateEncodingException;
import java.security.cert.X509Certificate;

import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.when;

/**
 * Regression test for empty catch block in MtlsHoKTokenUtil.dumpCertInfo
 * that silently swallows exceptions during certificate thumbprint calculation.
 *
 * The method declares "throws CertificateEncodingException" in its signature,
 * so exceptions from certificate processing should propagate, not be swallowed.
 */
class MtlsHoKTokenUtilDumpCertInfoTest {

    /**
     * Test that dumpCertInfo does NOT silently swallow CertificateEncodingException.
     * 
     * The correct behavior (per the method signature declaring throws CertificateEncodingException)
     * is that when a certificate's getEncoded() throws, the exception should propagate up
     * to the caller. The empty catch block } catch (Exception e) {} violates this contract.
     */
    @Test
    void dumpCertInfoShouldNotSwallowCertificateEncodingException() throws Exception {
        // Create a mock X509Certificate.
        // dumpCertInfo calls many methods on the cert. We must stub all to avoid NPE.
        // Crucially, getEncoded() is called TWICE:
        //   1) At line 151: certs[i].getEncoded().length  (OUTSIDE the try-catch)
        //   2) At line 154: getCertificateThumbprintInSHA256DERX509Base64UrlEncoded(certs[i])
        //      which internally calls cert.getEncoded() (INSIDE the try-catch)
        //
        // We make getEncoded() succeed on 1st call (line 151) and throw on 2nd call (line 154),
        // so we exercise the empty catch block at line 155.
        X509Certificate brokenCert = Mockito.mock(X509Certificate.class);

        // Stub methods called OUTSIDE the try-catch to avoid NPE before reaching line 153
        when(brokenCert.toString()).thenReturn("BrokenCert");
        // First call succeeds (line 151), second call throws (inside try at line 154)
        when(brokenCert.getEncoded())
            .thenReturn(new byte[]{1, 2, 3})
            .thenThrow(new CertificateEncodingException("Simulated encoding failure inside try block"));
        // Stub remaining methods called AFTER the try-catch to avoid NPE
        when(brokenCert.getTBSCertificate()).thenReturn(new byte[]{4, 5, 6});
        when(brokenCert.getSigAlgName()).thenReturn("SHA256withRSA");
        when(brokenCert.getType()).thenReturn("X.509");
        when(brokenCert.getIssuerDN()).thenReturn(new java.security.Principal() {
            @Override public String getName() { return "CN=issuer"; }
        });
        when(brokenCert.getSubjectDN()).thenReturn(new java.security.Principal() {
            @Override public String getName() { return "CN=subject"; }
        });

        X509Certificate[] certs = new X509Certificate[] { brokenCert };

        // Get the private dumpCertInfo method via reflection
        Method dumpCertInfoMethod = MtlsHoKTokenUtil.class.getDeclaredMethod("dumpCertInfo", X509Certificate[].class);
        dumpCertInfoMethod.setAccessible(true);

        // The method declares "throws CertificateEncodingException", so when a cert throws,
        // the exception SHOULD propagate. The empty catch block prevents this (the bug).
        // This assertion expects the exception to propagate (correct behavior).
        assertThrows(CertificateEncodingException.class, () -> {
            dumpCertInfoMethod.invoke(null, new Object[] { certs });
        }, "dumpCertInfo should propagate CertificateEncodingException, not swallow it silently");
    }
}

